pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // 1. Tighten admissible domain: must be same-length, non-empty, and each amount must satisfy the require check
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] == 0 || ((v[i] * 1e18) / v[i]) == 1e18);
        }

        // 2. The low-level call in C targets caddress, which is a hardcoded EOA with no code, so the call always succeeds silently.
