pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Dummy dummy;

    function setUp() public {
        c = new C();
        dummy = new Dummy();
    }

    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // ensure arrays are equal length and non-empty
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // ensure the sender is the required address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        // wrap the call in try/catch to capture success without reverting
        bool callOk;
        try c.transfer(_tos, v) returns (bool returned) {
            // if it didn't revert, returned must be true (since the dummy always succeeds the low-level call)
            assertTrue(returned);
            callOk = true;
        } catch {
            callOk = false;
        }

        // The property: if the transfer call completes, it must return true.
        // This holds for the reference because the external call always succeeds (dummy does not revert).
        // The mutant always returns false, which will be caught by assertTrue(returned).
    }
}

contract Dummy {
    // fallback that always succeeds
    fallback() external payable {}
}
